extends Node

func _pit_stats(bm, label: String) -> void:
	for pit in bm.epic_pit_centers:
		var pillars := 0
		var segs := 0
		var opens := 0
		for w in get_tree().get_nodes_in_group("walls"):
			if w.global_position.distance_to(pit) > 11.0:
				continue
			if w.pillar:
				pillars += 1
			elif absf(w.continuous_len) > 0.01:
				segs += 1
				if w.open_end:
					opens += 1
		print("%s PIT %s pillars=%d segs=%d open=%d" % [label, str(pit), pillars, segs, opens])

func _nearest_wall_dist(p: Vector3) -> float:
	var best := 999.0
	for w in get_tree().get_nodes_in_group("walls"):
		var d: float = p.distance_to(w.global_position)
		if d < best:
			best = d
	return best

func _ready() -> void:
	await get_tree().process_frame
	var scene = load("res://scenes/battle.tscn").instantiate()
	add_child(scene)
	await get_tree().process_frame
	var bm = null
	for n in get_tree().get_nodes_in_group("battle_manager"):
		bm = n
	if bm == null:
		for c in scene.get_children():
			if c is BattleManager:
				bm = c
	print("BM=%s" % str(bm != null))
	bm._generate_lane_edge_walls()
	bm._generate_high_ground_walls()
	bm._generate_outer_walls()
	bm._create_jungle()
	bm._generate_jungle_arc_walls()
	await get_tree().process_frame
	var total := 0
	var cont := 0
	var pill := 0
	var outer := 0
	var cont_pts: Array = []
	for w in get_tree().get_nodes_in_group("walls"):
		total += 1
		if w.pillar:
			pill += 1
		elif absf(w.continuous_len) > 0.01:
			cont += 1
			var th: float = w.rotation.y
			var half: float = absf(w.continuous_len) * 0.5
			var dir := Vector3(cos(th), 0.0, -sin(th))
			cont_pts.append([w.global_position - dir * half, w.global_position + dir * half])
		if w.outer:
			outer += 1
	print("WALL_TOTAL=%d CONT=%d PILLAR=%d OUTER=%d" % [total, cont, pill, outer])
	# 相邻连续墙的表面缝隙（取每个端点到其余段线段的最近距离）
	var gaps: Array = []
	for e in cont_pts:
		for ep in e:
			var best := 999.0
			for o in cont_pts:
				if o == e:
					continue
				var d: float = _seg_dist(ep, o[0], o[1])
				if d < best:
					best = d
			if best < 900.0:
				gaps.append(best)
	gaps.sort()
	if gaps.size() > 0:
		print("GAP median=%.3f min=%.3f max=%.3f n=%d" % [gaps[gaps.size() / 2], gaps[0], gaps[gaps.size() - 1], gaps.size()])
	_pit_stats(bm, "AFTER")
	# 分路野区入口缺口是否仍然通行（x=-47, z 22..31 沿线）
	var blocked := 0
	for zz in range(23, 31):
		if _nearest_wall_dist(Vector3(-47, 0, zz)) < 2.6:
			blocked += 1
	print("LANE_GAP_BLOCKED=%d/8" % blocked)
	# 中路上墙链存在性
	print("PROBE_DONE")
	get_tree().quit()

func _seg_dist(p: Vector3, a: Vector3, b: Vector3) -> float:
	var ab := b - a
	var l2 := ab.length_squared()
	if l2 < 0.0001:
		return p.distance_to(a)
	var t := clampf((p - a).dot(ab) / l2, 0.0, 1.0)
	return p.distance_to(a + ab * t)
