		print("GAP median=%.3f max=%.3f over25cm=%d/%d" % [gaps[gaps.size() / 2], gaps[gaps.size() - 1], over, gaps.size()])
	# 龙坑口：无端柱、有连续开放段
	for pit in bm.epic_pit_centers:
		var mouth_pillars := 0
		var open_segs := 0
		for w in get_tree().get_nodes_in_group("walls"):
