				if w.pillar:
					mouth_pillars += 1
				elif absf(w.continuous_len) > 0.01 and w.open_end:
					open_segs += 1
		print("PIT %s mouth_pillars=%d open_segs=%d" % [str(pit), mouth_pillars, open_segs])
	# 高地弧墙 / 分路内缘墙数量
	var hg := 0
	var lane_inner := 0
	for w in get_tree().get_nodes_in_group("walls"):
