			hg += 1
		if absf(w.global_position.x) > 46.0 and absf(w.global_position.x) < 48.0 and absf(w.global_position.z) <= 38.0:
			lane_inner += 1
	print("HG_SEGS=%d LANE_INNER_SEGS=%d" % [hg, lane_inner])
